#ifndef ORIVA_JSON_H
#define ORIVA_JSON_H
#include <stdlib.h>
#include <string.h>
#include <wchar.h>
#include <stdint.h>
typedef struct {int start,end,next;char type;} OJToken;
typedef struct {const char*s;int len,pos,count,capacity,failed;OJToken*t;} OJParser;
static int ojHex(char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:c>='A'&&c<='F'?c-'A'+10:-1;}
static void ojSpace(OJParser*p){while(p->pos<p->len&&strchr(" \t\r\n",p->s[p->pos]))p->pos++;}
static int ojNew(OJParser*p,char type){if(p->count>=1000000){p->failed=1;return -1;}if(p->count==p->capacity){int n=p->capacity?p->capacity*2:256;OJToken*t=(OJToken*)realloc(p->t,(size_t)n*sizeof(*t));if(!t){p->failed=1;return -1;}p->t=t;p->capacity=n;}int at=p->count++;p->t[at]=(OJToken){p->pos,0,0,type};return at;}
static int ojValue(OJParser*p,int depth){ojSpace(p);if(depth>64||p->pos>=p->len){p->failed=1;return -1;}char c=p->s[p->pos];int at=ojNew(p,c);if(at<0)return -1;
 if(c=='"'){p->pos++;int closed=0;while(p->pos<p->len){unsigned char x=p->s[p->pos++];if(x=='"'){closed=1;break;}if(x<32){p->failed=1;break;}if(x=='\\'){if(p->pos>=p->len){p->failed=1;break;}x=p->s[p->pos++];if(x=='u'){for(int i=0;i<4;i++)if(p->pos>=p->len||ojHex(p->s[p->pos++])<0){p->failed=1;break;}}else if(!strchr("\"\\/bfnrt",x)){p->failed=1;break;}}if(p->failed)break;}if(!closed)p->failed=1;
 }else if(c=='{'||c=='['){p->pos++;ojSpace(p);char end=c=='{'?'}':']';if(p->pos<p->len&&p->s[p->pos]==end)p->pos++;else for(;;){if(c=='{'){ojSpace(p);if(p->pos>=p->len||p->s[p->pos]!='"'){p->failed=1;break;}ojValue(p,depth+1);ojSpace(p);if(p->failed||p->pos>=p->len||p->s[p->pos++]!=':'){p->failed=1;break;}}ojValue(p,depth+1);ojSpace(p);if(p->failed||p->pos>=p->len){p->failed=1;break;}char x=p->s[p->pos++];if(x==end)break;if(x!=','){p->failed=1;break;}} 
 }else{int begin=p->pos;while(p->pos<p->len&&!strchr(" \t\r\n,]}",p->s[p->pos]))p->pos++;int n=p->pos-begin;const char*v=p->s+begin;if((n==4&&!memcmp(v,"true",4))||(n==5&&!memcmp(v,"false",5))||(n==4&&!memcmp(v,"null",4))){}else{int i=0;if(i<n&&v[i]=='-')i++;if(i>=n)p->failed=1;else if(v[i]=='0')i++;else if(v[i]>='1'&&v[i]<='9'){while(i<n&&v[i]>='0'&&v[i]<='9')i++;}else p->failed=1;if(i<n&&v[i]=='.'){i++;int d=i;while(i<n&&v[i]>='0'&&v[i]<='9')i++;if(i==d)p->failed=1;}if(i<n&&(v[i]=='e'||v[i]=='E')){i++;if(i<n&&(v[i]=='+'||v[i]=='-'))i++;int d=i;while(i<n&&v[i]>='0'&&v[i]<='9')i++;if(i==d)p->failed=1;}if(i!=n)p->failed=1;}}
 p->t[at].end=p->pos;p->t[at].next=p->count;return p->failed?-1:at;}
static OJToken*ojParse(const char*s,int*count){if(!s)return NULL;size_t len=strlen(s);if(len>32*1024*1024)return NULL;OJParser p={s,(int)len,0,0,0,0,NULL};ojValue(&p,0);ojSpace(&p);if(p.failed||p.pos!=p.len){free(p.t);return NULL;}*count=p.count;return p.t;}
static int ojField(const char*s,const OJToken*t,int object,const char*key){if(object<0||t[object].type!='{')return -1;for(int i=object+1;i<t[object].next;){int v=i+1;if(t[i].type!='"'||v>=t[object].next)return -1;if(t[i].end-t[i].start==(int)strlen(key)+2&&!memcmp(s+t[i].start+1,key,strlen(key)))return v;i=t[v].next;}return -1;}
static int ojTrue(const char*s,const OJToken*t,int at){return at>=0&&t[at].end-t[at].start==4&&!memcmp(s+t[at].start,"true",4);}
static char*ojRaw(const char*s,const OJToken*t,int at){if(at<0)return NULL;size_t n=(size_t)(t[at].end-t[at].start);char*out=(char*)malloc(n+1);if(out){memcpy(out,s+t[at].start,n);out[n]=0;}return out;}
static wchar_t*ojWide(const char*s,const OJToken*t,int at){if(at<0||t[at].type!='"')return NULL;int i=t[at].start+1,end=t[at].end-1,n=0;wchar_t*out=(wchar_t*)calloc((size_t)(end-i)+1,sizeof(wchar_t));if(!out)return NULL;while(i<end){uint32_t cp=(unsigned char)s[i++];if(cp=='\\'){if(i>=end)goto bad;char e=s[i++];if(e=='u'){cp=0;for(int k=0;k<4;k++){if(i>=end||ojHex(s[i])<0)goto bad;cp=(cp<<4)|(unsigned)ojHex(s[i++]);}if(cp>=0xd800&&cp<=0xdbff){if(i+6>end||s[i]!='\\'||s[i+1]!='u')goto bad;i+=2;uint32_t low=0;for(int k=0;k<4;k++){if(ojHex(s[i])<0)goto bad;low=(low<<4)|(unsigned)ojHex(s[i++]);}if(low<0xdc00||low>0xdfff)goto bad;out[n++]=(wchar_t)cp;out[n++]=(wchar_t)low;continue;}if(cp>=0xdc00&&cp<=0xdfff)goto bad;}else{switch(e){case '"':cp='"';break;case '\\':cp='\\';break;case '/':cp='/';break;case 'b':cp='\b';break;case 'f':cp='\f';break;case 'n':cp='\n';break;case 'r':cp='\r';break;case 't':cp='\t';break;default:goto bad;}}}else if(cp>=0x80){int extra;uint32_t min;if(cp>=0xc2&&cp<=0xdf){extra=1;min=0x80;cp&=31;}else if(cp>=0xe0&&cp<=0xef){extra=2;min=0x800;cp&=15;}else if(cp>=0xf0&&cp<=0xf4){extra=3;min=0x10000;cp&=7;}else goto bad;for(int k=0;k<extra;k++){if(i>=end||((unsigned char)s[i]&0xc0)!=0x80)goto bad;cp=(cp<<6)|((unsigned char)s[i++]&63);}if(cp<min||cp>0x10ffff||(cp>=0xd800&&cp<=0xdfff))goto bad;}if(cp>0xffff){cp-=0x10000;out[n++]=(wchar_t)(0xd800+(cp>>10));out[n++]=(wchar_t)(0xdc00+(cp&1023));}else out[n++]=(wchar_t)cp;}return out;bad:free(out);return NULL;}
#endif
